-- 1. What is the total revenue generated by male vs female customers?
SELECT gender, SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY gender;

-- 2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
AND purchase_amount > (
	SELECT AVG(purchase_amount) AS average_purchase_amount
	FROM customer
);

-- 3. Which are the top 5 products with the highest average review rating
SELECT item_purchased, ROUND(AVG(review_rating::numeric),2) AS average_rating
FROM customer
GROUP BY item_purchased
ORDER BY average_rating DESC
LIMIT 5;

-- 4. Compare the average purchased amount between standard and express shipping
SELECT shipping_type, ROUND(AVG(purchase_amount),2) AS average_purchased_amount
FROM customer
WHERE shipping_type IN ('Standard','Express')
GROUP BY shipping_type;

-- 5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers
SELECT subscription_status,
	COUNT(customer_id) AS total_customer,
	ROUND(AVG(purchase_amount),2) AS average_spend,
	SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue, average_spend DESC;

-- 6. Which 5 products have the highest percentage of purchases with discounts applied
WITH discounted_purchases AS (
	SELECT item_purchased, COUNT(*) AS discounted_counts
	FROM customer
	WHERE discount_applied = 'Yes'
	GROUP BY item_purchased
),
total_purchases AS (
	SELECT item_purchased, COUNT(*) AS total_counts
	FROM customer
	GROUP BY item_purchased
)
SELECT d.item_purchased,
	ROUND(discounted_counts::numeric / total_counts * 100,2) AS discount_percentage
FROM discounted_purchases d
JOIN total_purchases t
ON d.item_purchased = t.item_purchased
ORDER BY discount_percentage DESC
LIMIT 5;

-- 2nd method:
SELECT item_purchased,
	ROUND(100 * SUM(CASE
		WHEN discount_applied = 'Yes' THEN 1
		ELSE 0
	END) / COUNT(*)::numeric,2) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

-- 7. Segment customers into New, Returning and loyal based on their total number of previous purchases
-- and show the count of each segment
WITH cus_segment AS (
	SELECT (
		CASE
			WHEN previous_purchases = 1 THEN 'New'
			WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
			ELSE 'Loyal'
		END
	) AS customer_segment
	FROM customer
)
SELECT customer_segment, COUNT(customer_segment)
FROM cus_segment
GROUP BY customer_segment;

-- 8. What are the top 3 most purchased products within each category?
WITH item_counts AS (
	SELECT category, item_purchased, COUNT(customer_id) AS total_orders,
	ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_ranked
	FROM customer
	GROUP BY category, item_purchased
)
SELECT item_ranked, category, item_purchased, total_orders
FROM item_counts
WHERE item_ranked <= 3;

-- 9. Are custoemrs who are repeat buyers (more than 5 previous purchase) also likely to subscribe?
SELECT subscription_status, COUNT(customer_id) AS repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

-- 10. What is the revenue contribution of each age group?
SELECT age_group, SUM(purchase_amount) AS revenue_contribution
FROM customer
GROUP BY age_group
ORDER BY revenue_contribution  DESC;

